/// 📨️ Original command ownership moves once from the live caller into its admitted Store owner.
#[derive(semio_framework_value::RetireOwned)]
pub enum ArtifactNativeVcsRequest {
 Undo{lane:HistoryLane,policy:UndoPolicy},Redo{lane:HistoryLane},
 CommitCheckpoint{message:Option<String>,authors:Vec<Author>},CreateAlternative{name:String},
 CheckoutCheckpoint{checkpoint_id:String},SwitchAlternative{alternative_id:String},
}
/// 🏷️ Fixed command identity crosses erased member and SDK boundaries without copying a history row.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum ArtifactNativeVcsKind{Undo,Redo,CommitCheckpoint,CreateAlternative,CheckoutCheckpoint,SwitchAlternative}
impl ArtifactNativeVcsRequest{
 /// 👁️ Borrows the request discriminator without cloning its original text or authors.
 pub fn kind(&self)->ArtifactNativeVcsKind{match self{Self::Undo{..}=>ArtifactNativeVcsKind::Undo,Self::Redo{..}=>ArtifactNativeVcsKind::Redo,Self::CommitCheckpoint{..}=>ArtifactNativeVcsKind::CommitCheckpoint,Self::CreateAlternative{..}=>ArtifactNativeVcsKind::CreateAlternative,Self::CheckoutCheckpoint{..}=>ArtifactNativeVcsKind::CheckoutCheckpoint,Self::SwitchAlternative{..}=>ArtifactNativeVcsKind::SwitchAlternative}}
}
/// 🪪️ Original edit rank and its target rank remain authenticated by the captured Store frontier.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct ArtifactNativeVcsSelection{pub redo:bool,pub position:usize,pub insertion:usize}
/// 🧾️ A result exists only after the bounded metadata producer publishes its matching candidate.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct ArtifactNativeVcsResult{pub operation:OperationId,pub generation:Generation,pub generation_before:u64,pub generation_after:u64,pub kind:ArtifactNativeVcsKind,pub selected:Option<ArtifactNativeVcsSelection>}
/// 📈️ Preparation, metadata readiness and publication are distinct observable states.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum ArtifactNativeVcsPhase{Selecting,Replaying,MetadataPending,AwaitingAck,Closing,Complete}
/// 📬️ One turn exposes the actual already reconciled physical progress.
pub struct ArtifactNativeVcsAdvance{pub phase:ArtifactNativeVcsPhase,pub progress:RetainedCloneProgress}

struct ArtifactNativeVcsFrame<P,M:Mutation<P>+Sync>{binding:OriginalSourceBinding,decoder:(u64,u64),frontier:(usize,u64,u64,[u8;32]),request:ManuallyDrop<Option<ArtifactNativeVcsRequest>>,selection:Option<ArtifactNativeVcsSelection>,key:Option<ArtifactHistoryKey>,scan:usize,stage:u8,source:ManuallyDrop<Option<Source<M>>>,issuer:ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<Edit<M>>>>>,issuer_close:Option<FactoryAuthority>,ids:ManuallyDrop<Option<Vec<MutationId>>>,text:ManuallyDrop<Option<String>>,operation:usize,replay:Option<Box<Option<ArtifactDerivedReplay<P,M>>>>,report_retirement:Option<Box<dyn ErasedSnapshotRetirement>>,finished:ManuallyDrop<Option<EditReplayResult<P,M>>>,publisher:Option<Box<OriginalReplayPublication<P,M>>>,checkpoint:Option<Box<OriginalCheckpointPublication<M>>>,checkout:Option<Box<OriginalCheckpointCheckout<P,M>>>,published:Option<OriginalReplayPublicationReceipt>,failure:ManuallyDrop<Option<ArtifactOriginalVcsFailure>>,retirement:RetainedCloneClose,result:Option<ArtifactNativeVcsResult>,result_taken:bool,closing:bool}
/// 🧳️ Only this pointer moves between turns; its original frame retains all source and cancellation custody.
pub struct ArtifactNativeVcsCommand<P,M:Mutation<P>+Sync>{frame:ManuallyDrop<Option<Box<ArtifactNativeVcsFrame<P,M>>>>}
fn refusal(text:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,text)}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn paid(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
fn demand(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn action(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce()->Result<RetainedCloneProgress,ValueError>)->Result<bool,OriginalTurnFailure>{let mut done=None;admit_original_construction(cx,&mut done,demand(d),|_|run().map(|p|((),p)))?;Ok(done.is_some())}
fn turn_delta(before:RetainedCloneProgress,after:RetainedCloneProgress)->Result<RetainedCloneProgress,ValueError>{let subtract=|after:usize,before:usize|after.checked_sub(before).ok_or_else(||refusal("native history original receipt moved backwards"));Ok(RetainedCloneProgress{copied_items:subtract(after.copied_items,before.copied_items)?,copied_bytes:subtract(after.copied_bytes,before.copied_bytes)?,retained_capacity_bytes:subtract(after.retained_capacity_bytes,before.retained_capacity_bytes)?,released_bytes:subtract(after.released_bytes,before.released_bytes)?})}
impl<P,M:Mutation<P>+Sync> ArtifactNativeVcsCommand<P,M>{
 /// 📏️ Original frame birth includes both initialized writes and the original request handoff.
 pub fn capture_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<ArtifactNativeVcsFrame<P,M>>(),..header::<(ArtifactNativeVcsFrame<P,M>,ArtifactNativeVcsFrame<P,M>,ArtifactNativeVcsRequest,Self)>()}}
 /// 📏️ Reports the pending fixed original producer birth without granting it a larger semantic body.
 pub fn next_construction_demands(&self)->Option<RetirementDemand>{let frame=self.frame.as_ref()?;if frame.closing||frame.result.is_some(){return None}match frame.stage{40 if frame.checkpoint.is_none()=>Some(OriginalCheckpointPublication::<M>::capture_demands()),41=>frame.checkpoint.as_ref()?.next_construction_demands(),50 if frame.checkout.is_none()=>Some(OriginalCheckpointCheckout::<P,M>::capture_demands()),51=>frame.checkout.as_ref()?.next_construction_demands(),_=>None}}
 /// 👁️ Borrows the original request without cloning its owned metadata.
 pub fn borrow_request(&self)->Option<&ArtifactNativeVcsRequest>{self.frame.as_ref()?.request.as_ref()}
 /// 🧭️ Metadata readiness never masquerades as visible publication.
 pub fn phase(&self)->ArtifactNativeVcsPhase{self.frame.as_ref().map_or(ArtifactNativeVcsPhase::Complete,|f|if f.closing{ArtifactNativeVcsPhase::Closing}else if f.result.is_some(){ArtifactNativeVcsPhase::AwaitingAck}else if f.stage<2{ArtifactNativeVcsPhase::Selecting}else if f.stage<12{ArtifactNativeVcsPhase::Replaying}else{ArtifactNativeVcsPhase::MetadataPending})}
 pub fn operation(&self)->Option<OperationId>{self.frame.as_ref().map(|f|f.binding.operation())}
 pub fn generation(&self)->Option<Generation>{self.frame.as_ref().map(|f|f.binding.generation())}
 pub fn selection(&self)->Option<ArtifactNativeVcsSelection>{self.frame.as_ref().and_then(|f|f.selection)}
 pub fn candidate(&self)->Option<&P>{self.frame.as_ref()?.finished.as_ref()?.state.as_deref()}
 pub fn borrow_result(&self)->Option<&ArtifactNativeVcsResult>{self.frame.as_ref()?.result.as_ref()}
 /// 🧯️ A semantic refusal stays as its actual owned VCS cause until paid closure.
 pub fn borrow_failure(&self)->Option<&VcsError>{self.frame.as_ref()?.failure.as_ref().map(|failure|failure.source())}
 pub fn terminal_is_empty(&self)->bool{self.frame.is_none()}
 pub fn begin_close(&mut self){if let Some(frame)=self.frame.as_mut(){frame.closing=true;}}
}
impl<P,M:Mutation<P>+Sync> Drop for ArtifactNativeVcsCommand<P,M>{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"original history command retains source or acknowledgement custody");}}
