 /// 🎟️ Captures one real original context; a denied birth keeps the exact request with its caller.
 fn admit_native_vcs_command(&self,request:&mut Option<ArtifactNativeVcsRequest>,cx:&mut StepContext<'_>,output:&mut Option<ArtifactNativeVcsCommand<P,M>>)->Result<bool,OriginalTurnFailure>;
 /// ⏭️ One actual context advances selection, original Report, private metadata or the common visible decision.
 fn advance_native_vcs_command(&mut self,owner:&mut ArtifactNativeVcsCommand<P,M>,cx:&mut StepContext<'_>)->Result<ArtifactNativeVcsAdvance,OriginalTurnFailure>;
 /// 📤️ Only the original caller receives the fixed publication receipt.
 fn take_native_vcs_result(&self,owner:&mut ArtifactNativeVcsCommand<P,M>,cx:&mut StepContext<'_>,output:&mut Option<ArtifactNativeVcsResult>)->Result<bool,OriginalTurnFailure>;
 /// 🤝️ Original acknowledgement schedules complete physical retirement without moving another result.
 fn ack_native_vcs_command(&self,owner:&mut ArtifactNativeVcsCommand<P,M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>;
